/* Authored educational scenarios, not reports of real company events.
 * Case tuple: title, situation, collaborators, success criterion, three steps.
 * Step tuple: label, action, artifact name, example artifact contents.
 * Project tuple: title, goal, inputs, first scope, three steps, deliverables,
 *               self-review question, optional extension.
 */
function learningExample(c,p,terms=[]){return {case:{title:c[0],situation:c[1],team:c[2],success:c[3],steps:c[4].map(s=>({label:s[0],action:s[1],artifact:s[2],contents:s[3]}))},project:{title:p[0],goal:p[1],inputs:p[2],scope:p[3],steps:p[4],deliverables:p[5],check:p[6],extension:p[7]},terms:terms.map(t=>({name:t[0],meaning:t[1]}))};}
